        action: "graduate",
        from: top,
        to: down,
        why: `${down} passed ${cand.ok}/${cand.n} (${pct(cand.rate)}) vs ${top} ${pct(cur.rate)}`,
        saving: (cur.perTask - cand.perTask) * cur.ok,
        perRun,
        perRunDown
